; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Cls
			dw kw_cls

			; 22: Print "VB self test 6"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 25: For i = 0 To 9
			dw kw_ztov, var_i
for1_t:

			; 26: buf(i) = i * 30
			dw kw_mulvl, var_i, 30, tmp1
			dw kw_aset8, arr_buf, var_i, tmp1

			; 27: Next
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; 28: Chk buf(9), 14          ' 270 And 255
			dw kw_lptrtov8, arr_buf+9, tmp0
			dw p_chk_c, tmp0, lit_14

			; 29: Chk buf(2), 60
			dw kw_lptrtov8, arr_buf+2, tmp0
			dw p_chk_c, tmp0, lit_60

			; 30: i = 3
			dw kw_ltov, 3, var_i

			; 31: Chk buf(i), 90
			dw kw_aget8, arr_buf, var_i, tmp0
			dw p_chk_c, tmp0, lit_90

			; 32: buf(0) = 255
			dw kw_ltolptr8, 255, arr_buf

			; 33: Chk buf(0), 255
			dw kw_lptrtov8, arr_buf, tmp0
			dw p_chk_c, tmp0, lit_255

			; 34: Chk ByteSum(buf), 255 + 30 + 60 + 90 + 120 + 150 + 180 + 210 + 240 + 14
			dw p_bytesum_c, ad_arr_buf
			dw p_chk_c, var_bytesum_bytesum, lit_1349

			; 37: ReDim dyn(5)
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 6, 1

			; 38: Chk UBound(dyn), 5
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_5

			; 39: Chk LBound(dyn), 0
			dw kw_lbound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_0

			; 40: For i = 0 To 5
			dw kw_ztov, var_i
for2_t:

			; 41: dyn(i) = i * i
			dw kw_mulvv, var_i, var_i, tmp2
			dw kw_pset, pa_dyn, var_i, tmp2

			; 42: Next
			dw kw_next1l_n, var_i, 5, for2_t
for2_e:

			; 43: Chk dyn(5), 25
			dw kw_pget, pa_dyn, lit_5, tmp0
			dw p_chk_c, tmp0, lit_25

			; 44: ReDim Preserve dyn(BIGN)
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 21, 0

			; 45: Chk UBound(dyn), 20
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_20

			; 46: Chk dyn(4), 16
			dw kw_pget, pa_dyn, lit_4, tmp0
			dw p_chk_c, tmp0, lit_16

			; 47: dyn(20) = 7
			dw kw_pset, pa_dyn, lit_20, lit_7

			; 48: Chk dyn(20), 7
			dw kw_pget, pa_dyn, lit_20, tmp0
			dw p_chk_c, tmp0, lit_7

			; 49: ReDim dyn(1 To 3)
			dw kw_redim, pa_dyn, pa_dyn_data, 1, 2, 3, 1

			; 50: Chk LBound(dyn), 1
			dw kw_lbound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_1

			; 51: Chk dyn(1), 0           ' cleared without Preserve
			dw kw_pget, pa_dyn, lit_1, tmp0
			dw p_chk_c, tmp0, lit_0

			; 52: dyn(3) = 9
			dw kw_pset, pa_dyn, lit_3, lit_9

			; 53: Chk Total(dyn), 9
			dw p_total_c, pa_dyn
			dw p_chk_c, var_total_total, lit_9

			; 54: Erase dyn
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 0, 0

			; 55: Chk UBound(dyn), -1
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_m1

			; 57: ReDim names(2)
			dw kw_redim, pa_names, pa_names_data, 0, 41, 3, 1

			; 58: names(1) = "dyn"
			dw kw_psets, pa_names, lit_1, str1

			; 59: Chk Len(names(1)), 3
			dw kw_pget, pa_names, lit_1, stmp0
			dw kw_strlen, stmp0, tmp0
			dw p_chk_c, tmp0, lit_3

			; 60: ReDim big(1)
			dw kw_redim, pa_big, pa_big_data, 0, 4, 2, 1

			; 61: big(1) = 100000
			dw kw_pset, pa_big, lit_1, llit_100000

			; 62: Chk big(1) \ 1000, 100
			dw kw_pget, pa_big, lit_1, ltmp0
			dw kw_l_div, ltmp0, llit_1000, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_100

			; 65: fixed(2) = 5
			dw kw_ltov, 5, arr_fixed+4

			; 66: Erase fixed
			dw kw_erase, arr_fixed, 10

			; 67: Chk fixed(2), 0
			dw p_chk_c, arr_fixed+4, lit_0

			; 70: ReDim recs(2)
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 3, 1
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 3, 1

			; 71: For i = 0 To 2
			dw kw_ztov, var_i
for3_t:

			; 72: recs(i).n = i * 5
			dw kw_mulvl, var_i, 5, tmp2
			dw kw_pset, pa_recs_n, var_i, tmp2

			; 73: recs(i).nm = "r" & i
			dw kw_strcstr, stmp3, var_i
			dw kw_strcpy, stmp2, str2
			dw kw_strcat, stmp2, stmp3
			dw kw_psets, pa_recs_nm, var_i, stmp2

			; 74: Next
			dw kw_next1l_n, var_i, 2, for3_t
for3_e:

			; 75: Chk UBound(recs), 2
			dw kw_ubound, pa_recs_n, tmp0
			dw p_chk_c, tmp0, lit_2

			; 76: Chk Len(recs(1).nm) + recs(2).n, 12
			dw kw_pget, pa_recs_nm, lit_1, stmp0
			dw kw_strlen, stmp0, tmp0
			dw kw_pget, pa_recs_n, lit_2, tmp1
			dw kw_add, tmp0, tmp1, tmp0
			dw p_chk_c, tmp0, lit_12

			; 77: ReDim Preserve recs(4)
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 5, 0
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 5, 0

			; 78: Chk recs(2).n, 10
			dw kw_pget, pa_recs_n, lit_2, tmp0
			dw p_chk_c, tmp0, lit_10

			; 79: Erase recs
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 0, 0
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 0, 0

			; 80: Chk UBound(recs), -1
			dw kw_ubound, pa_recs_n, tmp0
			dw p_chk_c, tmp0, lit_m1

			; 82: Print
			dw kw_printnl

			; 83: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str3
			dw kw_printint, var_bad
			dw kw_printstrvar, str4
			dw kw_printnl

			; 84: End
			dw kw_printnl0
			dw kw_printstrvar, str5
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 87: t = t + 1
			dw kw_inc, var_t

			; 88: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str6

			; 89: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if4_1

			; 90: Print "ok ";
			dw kw_printstrvar, str7

			; 91: Else
			dw if4_e_go
if4_1:

			; 92: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str8
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str9

			; 93: bad = bad + 1
			dw kw_inc, var_bad

			; 94: End If
if4_e:
			dw p_chk_r

; ============================================================
; function bytesum (normal mode)
; ============================================================

p_bytesum:

			; 98: Dim k As Integer

			; 99: ByteSum = 0
			dw kw_ztov, var_bytesum_bytesum

			; 100: For k = LBound(b) To UBound(b)
			dw kw_lbound, pa_bytesum_b, var_bytesum_k
			dw kw_ubound, pa_bytesum_b, for5_l
			dw kw_forupv_n, var_bytesum_k, for5_l, for5_e
for5_t:

			; 101: ByteSum = ByteSum + b(k)
			dw kw_ztov, tmp1
			dw kw_pget, pa_bytesum_b, var_bytesum_k, tmp1
			dw kw_add, var_bytesum_bytesum, tmp1, var_bytesum_bytesum

			; 102: Next
			dw kw_next1v_n, var_bytesum_k, for5_l, for5_t
for5_e:
			dw p_bytesum_r

; ============================================================
; function total (normal mode)
; ============================================================

p_total:

			; 106: Dim k As Integer

			; 107: Total = 0
			dw kw_ztov, var_total_total

			; 108: For k = LBound(a) To UBound(a)
			dw kw_lbound, pa_total_a, var_total_k
			dw kw_ubound, pa_total_a, for6_l
			dw kw_forupv_n, var_total_k, for6_l, for6_e
for6_t:

			; 109: Total = Total + a(k)
			dw kw_pget, pa_total_a, var_total_k, tmp1
			dw kw_add, var_total_total, tmp1, var_total_total

			; 110: Next
			dw kw_next1v_n, var_total_k, for6_l, for6_t
for6_e:
			dw p_total_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if4_e_go:			ld sp, if4_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_bytesum_c:		; call bytesum (normal)
			pop hl			; b() descriptor
			ld de, pa_bytesum_b
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_bytesum_bytesum), hl
			ld hl, 0
			ld (var_bytesum_k), hl
			ld (p_bytesum_rs), sp
			ld sp, p_bytesum
			jp ntc_xn
p_bytesum_r:		; end of bytesum
			ld sp, (p_bytesum_rs)
			jp ntc_xn
p_total_c:		; call total (normal)
			pop hl			; a() descriptor
			ld de, pa_total_a
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_total_total), hl
			ld hl, 0
			ld (var_total_k), hl
			ld (p_total_rs), sp
			ld sp, p_total
			jp ntc_xn
p_total_r:		; end of total
			ld sp, (p_total_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_i:			dw 0
ad_arr_buf:			dw arr_buf, 0, 0, 10, 1, 1		; array as an argument
var_bytesum_bytesum:			dw 0
var_total_total:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_bytesum_rs:			dw 0
var_bytesum_k:			dw 0
for5_l:			dw 0
p_total_rs:			dw 0
var_total_k:			dw 0
for6_l:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0
			db 40			; capacity
stmp0:			ds 41
			db 40			; capacity
stmp1:			ds 41
			db 40			; capacity
stmp2:			ds 41
			db 40			; capacity
stmp3:			ds 41
ltmp0:			dw 0, 0

; numbers passed by address (read only)
lit_14:			dw 14
lit_60:			dw 60
lit_90:			dw 90
lit_255:			dw 255
lit_1349:			dw 1349
lit_5:			dw 5
lit_0:			dw 0
lit_25:			dw 25
lit_20:			dw 20
lit_4:			dw 4
lit_16:			dw 16
lit_7:			dw 7
lit_1:			dw 1
lit_9:			dw 9
lit_3:			dw 3
lit_m1:			dw -1
llit_100000:			dw 34464, 1
llit_1000:			dw 1000, 0
lit_100:			dw 100
lit_2:			dw 2
lit_12:			dw 12
lit_10:			dw 10

; ============================================================
; Strings
; ============================================================

str0:			db "VB self test 6", 0
str1:			db "dyn", 0
str2:			db "r", 0
str3:			db " tests, ", 0
str4:			db " failed", 0
str5:			db "Press a key", 0
str6:			db ":", 0
str7:			db "ok ", 0
str8:			db "FAIL(", 0
str9:			db ") ", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call
ntc_rampt:		dw #7FC0		; the gate array's RAM setting now (B = port, C = value): the
								; Memory class keeps it, Graphics puts it back after drawing
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_forupv (normal mode copy) ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_gt_n

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_next1v (normal mode copy) ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1v_nc_n
			inc (hl)
ntc_n1v_nc_n:
			ld d, (hl)
			pop hl
			ld c, (hl)
			inc hl
			ld h, (hl)
			ld l, c
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvv ntc_mul
;kw_mulvv, <var1>, <var2>, <destvar>
kw_mulvv:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			jp ntc_mul

;## kw_mulvl ntc_mul
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop de
			jp ntc_mul

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpeqvv ntc_cmp
;kw_cpeqvv, <var1>, <var2>
kw_cpeqvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_eq

;## kw_lptrtov8
;kw_lptrtov8, <literaladdr>, <destvar>  - PEEK(literal)
kw_lptrtov8:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_ltolptr8
;kw_ltolptr8, <literal>, <literaladdr>  - POKE literal, literal
kw_ltolptr8:
			pop bc
			pop hl
			ld (hl), c
			ret

;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld a, (hl)
			ld (de), a
			ret

;## kw_redim kw_erase
;kw_redim, <descriptor>, <base>, <lower>, <size>, <count>, <clear>  - ReDim: fill the
;  descriptor (1 dimension); clear <> 0: zero the elements
kw_redim:
			pop hl
			pop de
			ld (ntc_rdbase), de
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			pop de
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld (hl), 0
			inc hl
			ld (hl), 0
			inc hl
			pop bc
			pop de
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld (hl), 1
			inc hl
			ld (hl), 0
			inc hl
			ld (hl), c
			inc hl
			ld (hl), b
			pop hl
			ld a, h
			or l
			ret z
			ld b, c
			ld hl, 0
ntc_rd_mul:
			add hl, de
			djnz ntc_rd_mul
			ld b, h
			ld c, l
			ld hl, (ntc_rdbase)
			jp ntc_zerofill
ntc_rdbase:		dw 0

;## kw_erase
;kw_erase, <base>, <bytes>  - Erase of a fixed size array: zero it
kw_erase:
			pop hl
			pop bc
; HL = start, BC = bytes: zero them, then the next keyword
ntc_zerofill:
			ld a, b
			or c
			ret z
			ld (hl), 0
			dec bc
			ld a, b
			or c
			ret z
			ld d, h
			ld e, l
			inc de
			ldir
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			pop hl
			ld bc, 0
ntc_strlen_loop:
			ld a, (hl)
			or a
			jr z, ntc_strlen_done
			inc hl
			inc c
			jr ntc_strlen_loop
ntc_strlen_done:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld ix, ntc_next
			jp ntc_itoa

;## ntc_paddr
; HL = descriptor, DE = index var: HL = element address, BC = element
; size. jp (ix). Descriptor (12 bytes): base, lower bound 1, lower bound 2,
; count 1, count 2, element size (a 1 dimension array has count 2 = 1)
ntc_paddr:
			ld a, (de)
			ld (ntc_pidx), a
			inc de
			ld a, (de)
			ld (ntc_pidx+1), a
			ld (ntc_pdesc), hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld (ntc_pbase), de
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld hl, (ntc_pidx)
			or a
			sbc hl, de
			ld (ntc_pidx), hl
; (ntc_pidx) = element number, (ntc_pbase) = base, (ntc_pdesc) = descriptor
ntc_pa_tail:
			ld hl, (ntc_pdesc)
			ld bc, 10
			add hl, bc
			ld c, (hl)
			inc hl
			ld b, (hl)
			ld de, (ntc_pidx)
			ld hl, (ntc_pbase)
			ld a, c
ntc_pa_mul:
			add hl, de
			dec a
			jr nz, ntc_pa_mul
			jp (ix)
ntc_pidx:		dw 0
ntc_pbase:		dw 0
ntc_pdesc:		dw 0

;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			pop hl
			pop de
			ld ix, ntc_pg_a
			jp ntc_paddr
ntc_pg_a:
			pop de
			ldir
			ret

;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			pop hl
			pop de
			ld ix, ntc_ps_a
			jp ntc_paddr
ntc_ps_a:
			ex de, hl
			pop hl
			ldir
			ret

;## kw_psets ntc_paddr kw_strcpy
;kw_psets, <descriptor>, <indexvar>, <src>  - String parameter array(index) = src, cut at the element
kw_psets:
			pop hl
			pop de
			ld ix, ntc_pss_a
			jp ntc_paddr
ntc_pss_a:
			ex de, hl
			pop hl
			ld a, c
			dec a
			ld b, a
			jp ntc_strcpy_loop

;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			pop hl
			inc hl
			inc hl
			pop de
			ldi
			ldi
			ret

;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			pop hl
			inc hl
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			inc hl
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			dec hl
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; Long (32 bit signed). A Long is 4 bytes, low byte first. Every
; argument is an address (a literal is a dw lo, hi in the data).
; Work space ntc_la / ntc_lb / ntc_lr / ntc_lt.
; ============================================================

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_ltoi
;kw_l_ltoi, <long>, <intdest>  - Long to Integer (low 16 bits)
kw_l_ltoi:
			pop hl
			pop de
			ldi
			ldi
			ret

;## ntc_lmul ntc_ldata
; ntc_la * ntc_lb -> ntc_lr (low 32 bits, same signed / unsigned). jp (ix)
ntc_lmul:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_lm_loop:
			ld hl, ntc_lb+3
			srl (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			jr nc, ntc_lm_skip
			ld de, ntc_la
			ld hl, ntc_lr
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
ntc_lm_skip:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			djnz ntc_lm_loop
			jp (ix)

;## ntc_lnegm
; HL = address of a Long: negate it in place. jp (ix)
ntc_lnegm:
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			jp (ix)

;## ntc_ldiv ntc_ldata ntc_lnegm
; ntc_la / ntc_lb signed, truncating: quotient in ntc_la, remainder (with
; the dividend's sign) in ntc_lr. Divide by 0: quotient 0, remainder =
; dividend. jp (ix) back.
ntc_ldiv:
			ld (ntc_lix), ix
			ld hl, (ntc_lb)
			ld a, h
			or l
			ld hl, (ntc_lb+2)
			or h
			or l
			jr nz, ntc_ld_nz
			ld hl, (ntc_la)
			ld (ntc_lr), hl
			ld hl, (ntc_la+2)
			ld (ntc_lr+2), hl
			ld hl, 0
			ld (ntc_la), hl
			ld (ntc_la+2), hl
			jp ntc_ld_out
ntc_ld_nz:
			ld a, (ntc_la+3)
			ld (ntc_lsgn), a
			ld b, a
			ld a, (ntc_lb+3)
			xor b
			ld (ntc_lcnt), a
			ld a, (ntc_la+3)
			or a
			jp p, ntc_ld_apos
			ld hl, ntc_la
			ld ix, ntc_ld_apos
			jp ntc_lnegm
ntc_ld_apos:
			ld a, (ntc_lb+3)
			or a
			jp p, ntc_ld_bpos
			ld hl, ntc_lb
			ld ix, ntc_ld_bpos
			jp ntc_lnegm
ntc_ld_bpos:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_ld_loop:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld hl, ntc_lr
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld de, ntc_lr
			ld hl, ntc_lb
			ld a, (de)
			sub (hl)
			ld (ntc_lt), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+3), a
			jr c, ntc_ld_no
			ld hl, (ntc_lt)
			ld (ntc_lr), hl
			ld hl, (ntc_lt+2)
			ld (ntc_lr+2), hl
			ld hl, ntc_la
			set 0, (hl)
ntc_ld_no:
			djnz ntc_ld_loop
			ld a, (ntc_lcnt)
			or a
			jp p, ntc_ld_qpos
			ld hl, ntc_la
			ld ix, ntc_ld_qpos
			jp ntc_lnegm
ntc_ld_qpos:
			ld a, (ntc_lsgn)
			or a
			jp p, ntc_ld_out
			ld hl, ntc_lr
			ld ix, ntc_ld_out
			jp ntc_lnegm
ntc_ld_out:
			ld ix, (ntc_lix)
			jp (ix)

;## kw_l_mul ntc_lmul ntc_ldata
;kw_l_mul, <a>, <b>, <dest>  - a * b
kw_l_mul:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			ld ix, ntc_lmu_back
			jp ntc_lmul
ntc_lmu_back:
			ld hl, ntc_lr
; copy the 4 bytes at HL to (ntc_ldst), then next keyword
ntc_lstore:
			ld de, (ntc_ldst)
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_div ntc_ldiv kw_l_mul
;kw_l_div, <a>, <b>, <dest>  - a \ b
kw_l_div:
			ld ix, ntc_ldv_back
ntc_ldv_go:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			jp ntc_ldiv
ntc_ldv_back:
			ld hl, ntc_la
			jp ntc_lstore

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based) - kept here for Tab
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_smode:		db 1			; screen mode (for the Graphics class)
ntc_fwa:		db 0			; ntc_fwcall: A on return
ntc_fwwrap:		db 0			; 1 = the last character made the firmware wrap
ntc_irqset:		db 0			; 1 = the firmware's fast ticker calls ntc_fwevt
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_irqix:		dw 0
NTC_FWBLK	equ #A5F0		; the fast ticker's event block (central 32K, below the firmware)
ntc_fwtop:		dw #A600		; the top of free RAM (#A5F0 with the fast ticker's block)

;## ntc_plat_fw ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_fwcall - IY = firmware address; A, BC, DE, HL go in and come
; back as the firmware leaves them (A also in ntc_fwa, carry kept).
; IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_fwcall:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call ntc_fwjp
			di
			ld sp, (ntc_ip)
			ld (ntc_fwa), a
			ld ix, (ntc_hostix)
			jp (ix)
ntc_fwjp:
			jp (iy)

;## ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_putc - A = character: TXT OUTPUT. The firmware wraps by itself after
; the last column, so only the column is counted here; a new line straight after
; that wrap is left out (it would leave an empty line)
ntc_plat_putc:
			ld iy, #BB5A			; TXT OUTPUT
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_fwcall
ntc_pc_back:
			ld ix, (ntc_pclink)
			xor a
			ld (ntc_fwwrap), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr nz, ntc_pc_done
			xor a				; the firmware wrapped to the next line
			ld (ntc_curx), a
			inc a
			ld (ntc_fwwrap), a
ntc_pc_done:
			jp (ix)

; ntc_plat_newline - CR LF (the firmware scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_fwwrap)
			or a
			jr z, ntc_nl_go
			xor a
			ld (ntc_fwwrap), a
			jp (ix)
ntc_nl_go:
			ld (ntc_pclink), ix
			ld a, 13
			ld iy, #BB5A
			ld ix, ntc_nl_lf
			jp ntc_fwcall
ntc_nl_lf:
			ld a, 10
			ld iy, #BB5A
			ld ix, ntc_nl_done
			jp ntc_fwcall
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			ld ix, (ntc_pclink)
			jp (ix)

; ntc_plat_backspace - back one, blank it, back again
ntc_plat_backspace:
			xor a
			ld (ntc_fwwrap), a
			ld a, (ntc_curx)
			or a
			jr nz, ntc_bs_col
			ld a, (ntc_cury)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_cury), a
			ld a, (ntc_scols)
ntc_bs_col:
			dec a
			ld (ntc_curx), a
			ld (ntc_pclink), ix
			ld a, 8
			ld iy, #BB5A
			ld ix, ntc_bs_sp
			jp ntc_fwcall
ntc_bs_sp:
			ld a, ' '
			ld iy, #BB5A
			ld ix, ntc_bs_back
			jp ntc_fwcall
ntc_bs_back:
			ld a, 8
			ld iy, #BB5A
			ld ix, (ntc_pclink)
			jp ntc_fwcall
ntc_bs_none:
			jp (ix)

; ntc_plat_cls - TXT CLEAR WINDOW, cursor home
ntc_plat_cls:
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld iy, #BB6C			; TXT CLEAR WINDOW
			jp ntc_fwcall

; ntc_plat_mode - A = mode 0-2 (3 = 2): SCR SET MODE (clears)
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			cp 1
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld (ntc_smode), a
			ld c, a
			ld a, b
			ld (ntc_scols), a
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld a, c
			ld iy, #BC0E			; SCR SET MODE
			jp ntc_fwcall

; ntc_plat_locate - H = column, L = row, 1 based: TXT SET CURSOR
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc h
ntc_lc_x:
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc l
ntc_lc_y:
			xor a
			ld (ntc_fwwrap), a
			ld a, h
			dec a
			ld (ntc_curx), a
			ld a, l
			dec a
			ld (ntc_cury), a
			ld iy, #BB75			; TXT SET CURSOR
			jp ntc_fwcall
ntc_pclink:		dw 0

;## ntc_plat_key ntc_plat_fw ntc_data
; ntc_plat_scankey - A = key from the firmware's buffer, or 0
ntc_plat_scankey:
			ld (ntc_kslink), ix
			ld iy, #BB09			; KM READ CHAR
			ld ix, ntc_ks_back
			jp ntc_fwcall
ntc_ks_back:
			ld ix, (ntc_kslink)
			jr c, ntc_ks_got
			xor a
			jp (ix)
ntc_ks_got:
			ld a, (ntc_fwa)
			jp (ix)

; ntc_plat_getkey - wait for a key: KM WAIT CHAR
ntc_plat_getkey:
			ld iy, #BB06			; KM WAIT CHAR
			jp ntc_fwcall
ntc_kslink:		dw 0

;## ntc_plat_exit ntc_plat_data ntc_plat_fw
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)	; the fast ticker out of the firmware's list
			or a
			jr z, ntc_ex_done
			xor a
			ld (ntc_irqset), a
			ld (ntc_irqix), ix
			ld hl, NTC_FWBLK
			ld iy, #BCE6		; KL DEL FAST TICKER
			ld ix, ntc_ex_back
			jp ntc_fwcall
ntc_ex_back:
			ld ix, (ntc_irqix)
ntc_ex_done:
			jp (ix)

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #A600 (the firmware's and AMSDOS's RAM is above), #A5F0 when the fast
; ticker's event block is there (Interrupt, interrupt classes). Called on the
; real stack (call / ret).
ntc_plat_memtop:
			ld hl, (ntc_fwtop)
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_buf		equ ntc_bss + 0		; 10 bytes
pa_dyn		equ ntc_bss + 10		; 12 bytes
pa_names		equ ntc_bss + 22		; 12 bytes
pa_big		equ ntc_bss + 34		; 12 bytes
arr_fixed		equ ntc_bss + 46		; 10 bytes
pa_dyn_data		equ ntc_bss + 56		; 42 bytes
pa_names_data		equ ntc_bss + 98		; 123 bytes
pa_big_data		equ ntc_bss + 221		; 8 bytes
pa_recs_n		equ ntc_bss + 229		; 12 bytes
pa_recs_n_data		equ ntc_bss + 241		; 10 bytes
pa_recs_nm		equ ntc_bss + 251		; 12 bytes
pa_recs_nm_data		equ ntc_bss + 263		; 205 bytes
pa_bytesum_b		equ ntc_bss + 468		; 12 bytes
pa_total_a		equ ntc_bss + 480		; 12 bytes
ntc_bss_size	equ 492
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "VBTEST6.BIN", ntc_start, ntc_end - ntc_start, ntc_start
